{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공연용 임시 무대 설치 시 처음부터 2년 허가 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "공연용 임시 무대는 전시회·박람회·공연에 해당하므로 존속기간은 1년 이내로만 허가받을 수 있습니다. 처음부터 2년 허가를 받을 수는 없습니다.",
          "b_ids": "도시공원:제13조제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 도시공원 조례상 허가 기간 만료 후 더 사용하려면 종료 일주일 전에 연장 신청 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "점용기간 만료 후 연장을 받으려면 기간만료 30일 전에 공원 또는 녹지관리청에 연장 신청을 해야 합니다. 따라서 종료 일주일 전에 신청하는 것은 정해진 신청 기한에 맞지 않습니다.",
          "b_ids": "도시공원:제13조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
